//! PHP's own constant values for the extensions phpx implements
//! (consts_table.rs is generated by tools/consts/gen.php).

use std::rc::Rc;

use rustc_hash::FxHashMap;

use crate::value::Value;

thread_local! {
    /// The built-in constants, built once per thread (their values are
    /// immutable) and shared by every request's interpreter.
    static BASE: Rc<FxHashMap<String, Value>> = Rc::new(crate::builtins::constants().into_iter().collect());
}

/// An interpreter's constants: the shared built-in ones, plus what this
/// request defined (and its own standard streams).
pub struct Constants {
    base: Rc<FxHashMap<String, Value>>,
    own: FxHashMap<String, Value>,
}

impl Constants {
    pub fn new() -> Self {
        let mut own = FxHashMap::default();
        crate::streams::std_streams(&mut |k, v| {
            own.insert(k.to_string(), v);
        });
        Constants { base: BASE.with(|b| b.clone()), own }
    }

    pub fn get(&self, name: &str) -> Option<&Value> {
        self.own.get(name).or_else(|| self.base.get(name))
    }

    pub fn contains_key(&self, name: &str) -> bool {
        self.own.contains_key(name) || self.base.contains_key(name)
    }

    pub fn insert(&mut self, name: String, v: Value) {
        self.own.insert(name, v);
    }

    /// What this interpreter defined itself (not the standard streams).
    pub fn defined(&self) -> Vec<(String, Value)> {
        self.own.iter().filter(|(k, _)| !matches!(k.as_str(), "STDIN" | "STDOUT" | "STDERR")).map(|(k, v)| (k.clone(), v.clone())).collect()
    }

    pub fn keys(&self) -> impl Iterator<Item = &String> {
        self.own.keys().chain(self.base.keys().filter(|k| !self.own.contains_key(*k)))
    }
}

pub enum C {
    I(i64),
    F(f64),
    S(&'static str),
    B(bool),
    N,
}

impl C {
    pub fn value(&self) -> Value {
        match self {
            C::I(n) => Value::Int(*n),
            C::F(f) => Value::Float(*f),
            C::S(s) => Value::str(s),
            C::B(b) => Value::Bool(*b),
            C::N => Value::Null,
        }
    }
}

/// The deprecation message for using built-in constant `name`, if any.
pub fn deprecation(name: &str) -> Option<&'static str> {
    static MAP: std::sync::OnceLock<rustc_hash::FxHashMap<&'static str, &'static str>> = std::sync::OnceLock::new();
    // Deprecated constants are all upper case: skip the map for the rest.
    if !name.bytes().next().is_some_and(|b| b.is_ascii_uppercase()) {
        return None;
    }
    MAP.get_or_init(|| crate::consts_table::DEPRECATED.iter().copied().collect()).get(name).copied()
}
